create function pg_temp.baseline_request(n integer,op text,p jsonb) returns jsonb language sql as $$
 select app_private.payment_history_local_baseline_request_v2('10000000-0000-4000-8000-000000403019',
  (value#>>array['baselines',(n-1)::text,'manifest','deviceId'])::uuid,'30000000-0000-4000-8000-000000403019',('60000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,
  'sha256:'||repeat(n::text,64),'sha256:'||repeat((n+2)::text,64),7,op,p)->'result' from corpus;
$$;
create function pg_temp.admit_baseline(n integer) returns jsonb language plpgsql as $$
declare f jsonb;start jsonb;l jsonb;review jsonb;upload uuid:=gen_random_uuid();receipt jsonb;begin
 select value->'baselines'->(n-1) into f from corpus;
 insert into public.payment_history_uploads(upload_id,shop_id,actor_kind,actor_id,object_key,file_name,file_sha256,byte_length,state,verified_at)
  values(upload,'10000000-0000-4000-8000-000000403019','pos_staff_manager','30000000-0000-4000-8000-000000403019','history/10000000-0000-4000-8000-000000403019/'||upload,'synthetic.w7history.zip',f->>'archiveSha256',(f->>'byteLength')::bigint,'verified',clock_timestamp());
 start:=pg_temp.baseline_request(n,'start',jsonb_build_object('request_key',gen_random_uuid(),'upload_id',upload,'local_dataset_id',f#>>'{manifest,localDatasetId}',
  'data_revision',f#>>'{manifest,dataRevision}','restore_epoch',f#>>'{manifest,restoreEpoch}','restore_lineage_id',f#>>'{manifest,restoreLineageId}','writer_epoch','1'));
 l:=public.payment_history_migration_worker_v1('claim','{}')->'run';
 if l->>'run_id' is distinct from start->>'run_id' then raise exception 'fixture_worker_claim_mismatch';end if;
 if jsonb_array_length(f->'objects')>0 then perform public.payment_history_migration_worker_v1('stage_objects',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'objects'));end if;
 if jsonb_array_length(f->'movements')>0 then perform public.payment_history_migration_worker_v1('stage_movements',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','rows',f->'movements'));end if;
 perform public.payment_history_migration_worker_v1('finish',jsonb_build_object('run_id',l->>'run_id','lease_token',l->>'lease_token','lease_fence',l->>'lease_fence','raw_manifest',f->>'rawManifest','analysis_digest',f->>'analysisDigest'));
 review:=pg_temp.baseline_request(n,'review',jsonb_build_object('run_id',start->>'run_id'));
 if review->>'can_apply' is distinct from 'true' then raise exception 'fixture_baseline_not_applicable';end if;
 receipt:=pg_temp.baseline_request(n,'apply',jsonb_build_object('run_id',start->>'run_id','request_key',gen_random_uuid(),'review_digest',review->>'review_digest'));
 return receipt;
end;$$;
insert into state values('baseline-a',pg_temp.admit_baseline(1)),('baseline-b',pg_temp.admit_baseline(2));
create function pg_temp.stage_case(label text) returns uuid language plpgsql as $$
declare x jsonb;page jsonb;begin
 select v.value into x from corpus c,jsonb_array_elements(c.value->'cases') v where v.value->>'name'=label;
 if x is null then raise exception 'fixture_case_missing';end if;
 perform app_private.payment_history_local_prepare_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,
  (x-array['name','shop_id','device_id','pages','local_receipt_json','local_receipt_sha256','local_decision'])||jsonb_build_object('writer_epoch','1','protocol_version',2));
 for page in select value from jsonb_array_elements(x->'pages') loop
  perform app_private.payment_history_local_stage_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,page||jsonb_build_object('operation_id',x->>'operation_id','content_digest',x->>'content_digest'));
 end loop;
 return (x->>'operation_id')::uuid;
end;$$;
create function pg_temp.review_case(label text,root text default null,token uuid default null) returns jsonb language sql as $$
 select app_private.payment_history_local_review_apply_page_v2((x->>'shop_id')::uuid,(x->>'device_id')::uuid,(x->>'operation_id')::uuid,coalesce(root,x->>'content_digest'),1,token)
 from corpus c,jsonb_array_elements(c.value->'cases') x where x->>'name'=label;
$$;
select is((select count(*) from public.payment_history_local_writer_contexts where shop_id='10000000-0000-4000-8000-000000403019'),2::bigint,'both actual selective baselines commit verified contexts');
select is((select count(*) from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000403019'),1::bigint,'empty baseline does not invent a movement');
select ok(not has_function_privilege('service_role','app_private.payment_history_local_review_apply_page_v2(uuid,uuid,uuid,text,integer,uuid)','EXECUTE'),'incomplete reviewer is not a service API');
select ok(not has_function_privilege('authenticated','app_private.payment_history_local_review_movement_v2(uuid,integer,integer)','EXECUTE'),'browser cannot classify a caller-supplied movement');
select ok(not has_table_privilege('service_role','public.payment_history_local_reviews','INSERT'),'review cache cannot be fabricated through table access');
select ok((select relrowsecurity from pg_class where oid='public.payment_history_local_reviews'::regclass),'review cache has RLS');
select lives_ok($$select pg_temp.stage_case('a-duplicate')$$,'real CLR duplicate bytes stage successfully');
insert into state values('a-duplicate',pg_temp.review_case('a-duplicate'));
select is((select value->>'state' from state where key='a-duplicate'),'reviewed','one bounded page reaches reviewed without a grant');
select is((select local_duplicates from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-duplicate')),1,'local duplicate classified from actual baseline');
select is((select canonical_duplicates from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-duplicate')),1,'canonical duplicate classified independently');
select is((select local_gross::text from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-duplicate')),'0','duplicate has no local revision or gross delta');
select is(pg_temp.review_case('a-duplicate'),(select value from state where key='a-duplicate'),'lost first review ACK recovers the same token and decision');
select is(pg_temp.review_case('a-duplicate',token=>(select (value->>'review_token')::uuid from state where key='a-duplicate')),(select value from state where key='a-duplicate'),'review replay does not count again');
select throws_ok($$select pg_temp.review_case('a-duplicate',root=>repeat('f',64))$$,'40001','payment_history_local_review_stale','content root cannot be switched');
select throws_ok($$select pg_temp.review_case('a-duplicate',token=>gen_random_uuid())$$,'40001','payment_history_local_review_stale','token cannot be replaced');
select lives_ok($$select pg_temp.stage_case('a-new')$$,'real CLR new movement stages independently');
insert into state values('a-new',pg_temp.review_case('a-new'));
select is((select local_inserted from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-new')),1,'new row is locally inserted');
select is((select canonical_inserted from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-new')),1,'new identity receives only a planned canonical version');
select is((select local_gross::text from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-new')),'2200','exact local gross agrees with actual CLR receipt');
select is((select canonical_gross::text from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='a-new')),'2200','exact canonical gross is computed by server review');
select is((select count(*) from public.payment_history_movement_versions where shop_id='10000000-0000-4000-8000-000000403019'),1::bigint,'private review creates no financial movement');
select is((select count(*) from public.payment_history_local_publications where shop_id='10000000-0000-4000-8000-000000403019' and grant_id is not null),0::bigint,'private review issues no authorization');
select is((select count(*) from public.pos_sales where shop_id='10000000-0000-4000-8000-000000403019'),0::bigint,'historical review has no native sale effect');
-- Independent canonical ownership fixture: the same merchant/identity is
-- already canonical, while POS B has a verified empty local baseline.
do $$declare x jsonb;f jsonb;sem jsonb;batch uuid:=gen_random_uuid();begin
 select v.value into x from corpus c,jsonb_array_elements(c.value->'cases') v where v.value->>'name'='b-locally-new-canonical-existing';
 select rec->'fields' into f from jsonb_array_elements(((x->'pages'->0)->>'page_json')::jsonb) rec where rec->>'kind'='movement';
 sem:=app_private.payment_history_local_transaction_v2(f,repeat('a',64));
 -- Seed the later canonical state explicitly; this is not an Undo/delivery test.
 update public.payment_history_movement_versions set active=false where shop_id='10000000-0000-4000-8000-000000403019' and external_id=f->>'external_id' and active;
 insert into public.payment_history_batches(batch_id,shop_id,origin,apply_operation_id,created_revision)
  values(batch,'10000000-0000-4000-8000-000000403019','local_migration',gen_random_uuid(),1);
 insert into public.payment_history_movement_versions(shop_id,merchant_id,external_namespace,external_id,identity_key,economic_digest,business_ticks,business_date,gross_clp,commission_clp,commission_vat_clp,net_clp,movement_kind,transaction_state,transaction,owner_batch_id,created_revision)
  values('10000000-0000-4000-8000-000000403019','c0000000-0000-4000-8000-000000403019',f->>'external_namespace',f->>'external_id',
   encode(extensions.digest(convert_to('10000000-0000-4000-8000-000000403019'||chr(31)||'getnet'||chr(31)||'c0000000-0000-4000-8000-000000403019'||chr(31)||(f->>'external_namespace')||chr(31)||(f->>'external_id'),'UTF8'),'sha256'),'hex'),
   app_private.payment_history_economic_digest_v1(app_private.payment_history_economics_v1(sem)),(f->>'business_ticks')::bigint,'2024-02-01',1500,20,null,1480,'Sale','ABONADO',sem,batch,1);
end;$$;
select lives_ok($$select pg_temp.stage_case('b-locally-new-canonical-existing')$$,'second POS stages its own actual CLR bytes');
insert into state values('b-new',pg_temp.review_case('b-locally-new-canonical-existing'));
select is((select local_inserted from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='b-new')),1,'POS B local insertion does not become a local duplicate');
select is((select canonical_duplicates from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='b-new')),1,'POS B observes canonical duplicate independently');
select is((select canonical_gross::text from public.payment_history_local_reviews where operation_id=(select (value->>'operation_id')::uuid from state where key='b-new')),'0','canonical duplicate adds no gross');
select ok((select local_inserted and not canonical_owned from public.payment_history_local_review_movements where operation_id=(select (value->>'operation_id')::uuid from state where key='b-new')),'local insertion never acquires canonical ownership');
update public.payment_history_merchant_aliases set active=false where shop_id='10000000-0000-4000-8000-000000403019';
select throws_ok($$select pg_temp.review_case('b-locally-new-canonical-existing')$$,'40001','payment_history_local_review_stale','mapping revocation invalidates the prepared decision');
update public.payment_history_merchant_aliases set active=true where shop_id='10000000-0000-4000-8000-000000403019';
update public.payment_history_runtime set revision=revision+1 where shop_id='10000000-0000-4000-8000-000000403019';
select throws_ok($$select pg_temp.review_case('a-new')$$,'40001','payment_history_local_review_stale','changed canonical revision invalidates a review before grant');
select * from finish();
rollback;
